<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany,BelongsToMany};
class Conversation extends Model { protected $fillable=['type','name','avatar','created_by','last_message_id']; public function creator(): BelongsTo{return $this->belongsTo(User::class,'created_by');} public function memberships(): HasMany{return $this->hasMany(ConversationMember::class);} public function members(): BelongsToMany{return $this->belongsToMany(User::class,'conversation_members')->withPivot(['role','joined_at','last_read_message_id'])->withTimestamps();} public function messages(): HasMany{return $this->hasMany(Message::class);} public function lastMessage(): BelongsTo{return $this->belongsTo(Message::class,'last_message_id');} public function getAvatarUrlAttribute(): ?string{return $this->avatar ? \Storage::disk('public')->url($this->avatar):null;} }
